css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .long-fila{display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 6px;}
.mz .long-caja{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 8px 10px; min-height: 38px; display: flex; align-items: center;}
.mz .long-linea{letter-spacing: 1px; font-size: 18px; font-weight: 700; font-family: sans-serif;}
.mz .pareja-fila{display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 6px;}
.mz .pareja-caja{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 8px 10px; min-height: 32px; display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 700; text-align: center;}
.mz .orden-fila{display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin-bottom: 8px;}
.mz .orden-caja{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 8px 6px; min-height: 50px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px;}
.mz .orden-nombre{font-size: 14px; font-weight: 700; text-align: center;}
.mz .orden-hueco{width: 26px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px;}
